(()=>{"use strict";const r=window.BarfordSupabase;if(!r)return;async function m({eventId:i,clubName:c,layoutName:t,externalClubId:g=null,externalCourseId:h=null,men:n,women:l}){if(!i||!c||!t||n?.holes?.length!==18||l?.holes?.length!==18)throw new Error("A club, exact course and complete men\u2019s and women\u2019s cards are required.");const d=await r.from("course_scorecards").select("id").ilike("course_name",c).ilike("course_layout",t).maybeSingle();if(d.error)throw d.error;let o=d.data?.id;if(!o){const e=await r.from("course_scorecards").insert({course_name:c,course_layout:t}).select("id").single();if(e.error)throw e.error;o=e.data.id}for(const[e,u]of[["men",n],["women",l]]){const a=await r.from("course_scorecard_tees").upsert({scorecard_id:o,playing_category:e,tee_name:u.name||(e==="men"?"Yellow":"Red")},{onConflict:"scorecard_id,playing_category"}).select("id").single();if(a.error)throw a.error;const f=await r.from("course_scorecard_holes").delete().eq("tee_id",a.data.id);if(f.error)throw f.error;const w=await r.from("course_scorecard_holes").insert(u.holes.map(s=>({tee_id:a.data.id,hole_number:s.hole??s.hole_number,par:s.par,yards:s.yards,stroke_index:s.stroke_index})));if(w.error)throw w.error}const _=await r.from("events").update({course_scorecard_id:o,selected_course_name:t,uk_golf_club_id:g||null,uk_golf_course_id:h||null,scorecards_status:"course_verified",updated_at:new Date().toISOString()}).eq("id",i);if(_.error)throw _.error;return o}window.BarfordCourseLayouts={saveLayout:m}})();
